import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadBhojaData(){const e=readFileSync(resolve(__dirname,"../../bhoja-malwa-explorer/bhoja-data.js"),"utf-8");return new Function(e+"\nreturn { BHOJA_INFO, SCHOLARLY_TREATISES, BHOJPUR_ARCHITECTURE, TIMELINE_EVENTS, REFERENCES };")()}describe("Bhoja of Malwa Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadBhojaData()}),describe("BHOJA_INFO metadata",()=>{it("contains correct Raja Bhoja metadata and Paramara dynasty",()=>{expect(e.BHOJA_INFO.id).toBe("bhoja-malwa"),expect(e.BHOJA_INFO.title).toContain("Bhoja of Malwa"),expect(e.BHOJA_INFO.dynasty).toContain("Paramara"),expect(e.BHOJA_INFO.architecturalMasterpiece).toContain("Bhojeshwar Temple")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.BHOJA_INFO.quickStats)).toBe(!0),expect(e.BHOJA_INFO.quickStats.length).toBe(6)})}),describe("SCHOLARLY_TREATISES & BHOJPUR_ARCHITECTURE",()=>{it("contains Samarangana Sutradhara and Bhojeshwar temple details",()=>{expect(Array.isArray(e.SCHOLARLY_TREATISES)).toBe(!0),expect(e.SCHOLARLY_TREATISES.length).toBeGreaterThanOrEqual(4);const a=e.SCHOLARLY_TREATISES.find(e=>e.title.includes("Samarangana"));expect(a).toBeDefined(),expect(e.BHOJPUR_ARCHITECTURE.templeName).toContain("Bhojeshwar"),expect(Array.isArray(e.BHOJPUR_ARCHITECTURE.architectureNotes)).toBe(!0)})}),describe("TIMELINE_EVENTS & REFERENCES",()=>{it("contains reign timeline and reference citations",()=>{expect(Array.isArray(e.TIMELINE_EVENTS)).toBe(!0),expect(e.TIMELINE_EVENTS.length).toBeGreaterThanOrEqual(4),expect(Array.isArray(e.REFERENCES)).toBe(!0),expect(e.REFERENCES.length).toBeGreaterThanOrEqual(2)})})});